import { test, expect } from '@playwright/test';

test.describe('Password Reset Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/reset-password');
  });

  test('should display confirmation message after password reset', async ({ page }) => {
    await page.fill(getByLabel('Email'), 'user@example.com');
    await page.click(getByRole('button', { name: 'Reset Password' }));

    const confirmationMessage = await page.getByText('A confirmation link has been sent to your email.');
    await expect(confirmationMessage).toBeVisible();
  });

  test('should not display confirmation message for invalid email', async ({ page }) => {
    await page.fill(getByLabel('Email'), 'invalid-email');
    await page.click(getByRole('button', { name: 'Reset Password' }));

    const errorMessage = await page.getByText('Please enter a valid email address.');
    await expect(errorMessage).toBeVisible();
  });
});
